#include <stdio.h>
#include <math.h>

#define W 2400
#define H 1800

static const double CX = 0.0, CY = -0.5, CZ = -5.0, RAD = 1.0, PY = -1.5;
static const double LX = 0.5773502691896258, LY = 0.5773502691896258, LZ = -0.5773502691896258;

static int q(double c)
{
    int v;
    if (c < 0.0) c = 0.0;
    v = (int)(256.0 * c);
    if (v > 255) v = 255;
    return v;
}

int main(void)
{
    FILE *f = fopen("reconstructed.ppm", "w");
    int i, j;
    if (!f) return 1;
    fprintf(f, "P3\n%d %d\n255\n", W, H);
    for (j = 0; j < H; j++) {
        for (i = 0; i < W; i++) {
            double u = (2.0 * (i + 0.5) / W - 1.0) * ((double)W / (double)H);
            double v = 1.0 - 2.0 * (j + 0.5) / H;
            double dx = u, dy = v, dz = -1.0;
            double n = sqrt(dx * dx + dy * dy + dz * dz);
            double ts, tp, b, c, disc, r, g, bl;
            dx /= n; dy /= n; dz /= n;

            ts = -1.0;
            b = dx * (0.0 - CX) + dy * (0.0 - CY) + dz * (0.0 - CZ);
            c = CX * CX + CY * CY + CZ * CZ - RAD * RAD;
            disc = b * b - c;
            if (disc > 0.0) {
                double t0 = -b - sqrt(disc);
                if (t0 > 1e-6) ts = t0;
            }
            tp = -1.0;
            if (dy < 0.0) tp = PY / dy;

            if (ts > 0.0 && (tp < 0.0 || ts < tp)) {
                double px = ts * dx, py = ts * dy, pz = ts * dz;
                double nx = (px - CX) / RAD, ny = (py - CY) / RAD, nz = (pz - CZ) / RAD;
                double d = nx * LX + ny * LY + nz * LZ;
                double s;
                if (d < 0.0) d = 0.0;
                s = 0.2 + 0.8 * d;
                r = 1.0 * s; g = 0.2 * s; bl = 0.2 * s;
            } else if (tp > 0.0) {
                double px = tp * dx, pz = tp * dz;
                double ox, oy, oz, bb, cc, dd, base, s;
                int chk = ((int)floor(px) + (int)floor(pz)) & 1;
                base = chk ? 0.4 : 0.9;
                ox = px - CX; oy = PY - CY; oz = pz - CZ;
                bb = ox * LX + oy * LY + oz * LZ;
                cc = ox * ox + oy * oy + oz * oz - RAD * RAD;
                dd = bb * bb - cc;
                s = 0.2 + 0.8 * 0.5773502691896258;
                if (dd > 0.0) {
                    double t0 = -bb - sqrt(dd);
                    double t1 = -bb + sqrt(dd);
                    if (t1 > 1e-4 && t0 < 1e30) {
                        if (t0 > 1e-4 || t1 > 1e-4) s = 0.2;
                    }
                }
                r = base * s; g = base * s; bl = base * s;
            } else {
                double t = 0.5 * (dy + 1.0);
                r = (1.0 - t) + t * 0.5;
                g = (1.0 - t) + t * 0.7;
                bl = (1.0 - t) + t * 1.0;
            }
            fprintf(f, "%d %d %d\n", q(r), q(g), q(bl));
        }
    }
    fclose(f);
    return 0;
}

