#include <stdio.h>
#include <math.h>

typedef struct { float x, y, z; } V;
typedef struct { V o, d; } Ray;
typedef struct { float t; V p, n; int hit; } Hit;

static V vc(float x, float y, float z) { V r; r.x = x; r.y = y; r.z = z; return r; }
static V vadd(V a, V b) { return vc(a.x + b.x, a.y + b.y, a.z + b.z); }
static V vsub(V a, V b) { return vc(a.x - b.x, a.y - b.y, a.z - b.z); }
static V vmul(V a, float t) { return vc(a.x * t, a.y * t, a.z * t); }
static float vdot(V a, V b) { return a.x * b.x + a.y * b.y + a.z * b.z; }
static float vlen(V a) { return (float)sqrt((double)vdot(a, a)); }
static V vnorm(V a) { float l = vlen(a); return vc(a.x / l, a.y / l, a.z / l); }

static Ray ray_create(V o, V d) { Ray r; r.o = o; r.d = vnorm(d); return r; }
static V ray_at(Ray r, float t) { return vadd(r.o, vmul(r.d, t)); }

static Hit sphere_hit(V ctr, float rad, Ray r)
{
    Hit h; V oc; float a, b, c, disc, a2, t;
    h.t = 0.0f; h.p = vc(0, 0, 0); h.n = vc(0, 0, 0); h.hit = 0;
    oc = vsub(r.o, ctr);
    a = vdot(r.d, r.d);
    b = vdot(oc, r.d); b = b + b;
    c = vdot(oc, oc) - rad * rad;
    disc = b * b - 4.0f * a * c;
    if (0.0f > disc) return h;
    a2 = a + a;
    t = (float)(((double)(-b) - sqrt((double)disc)) / (double)a2);
    if (0.001f > t) {
        t = (float)(((double)(-b) + sqrt((double)disc)) / (double)a2);
        if (0.001f > t) return h;
    }
    h.hit = 1; h.t = t; h.p = ray_at(r, t); h.n = vnorm(vsub(h.p, ctr));
    return h;
}

static Hit plane_hit(float py, Ray r)
{
    Hit h; float t;
    h.t = 0.0f; h.p = vc(0, 0, 0); h.n = vc(0, 0, 0); h.hit = 0;
    if (1e-4f > fabsf(r.d.y)) return h;
    t = (py - r.o.y) / r.d.y;
    if (0.001f > t) return h;
    h.hit = 1; h.t = t; h.p = ray_at(r, t); h.n = vc(0.0f, 1.0f, 0.0f);
    return h;
}

static V sky_color(Ray r)
{
    float t = 0.5f * (r.d.y + 1.0f);
    V w = vc(1.0f, 1.0f, 1.0f), b = vc(0.5f, 0.7f, 1.0f);
    return vadd(vmul(w, 1.0f - t), vmul(b, t));
}

static V trace(V sc, float sr, V light, Ray r)
{
    Hit hs = sphere_hit(sc, sr, r);
    Hit hp = plane_hit(-1.5f, r);
    Hit h; int is_sphere; float diff, amb, inten; V base, so;
    if (hs.hit && (!hp.hit || hp.t > hs.t)) { h = hs; is_sphere = 1; }
    else if (hp.hit) { h = hp; is_sphere = 0; }
    else return sky_color(r);
    diff = (float)fmax((double)vdot(h.n, light), 0.0);
    so = vadd(h.p, vmul(h.n, 0.001f));
    if (sphere_hit(sc, sr, ray_create(so, light)).hit) diff = 0.0f;
    amb = 0.2f;
    inten = (1.0f - amb) * diff + amb;
    if (is_sphere) base = vc(1.0f, 0.2f, 0.2f);
    else {
        int chk = ((int)(floor((double)h.p.x) + floor((double)h.p.z)) & 1) == 0;
        base = chk ? vc(0.9f, 0.9f, 0.9f) : vc(0.4f, 0.4f, 0.4f);
    }
    return vmul(base, inten);
}

static int q(float c)
{
    c = (float)fmin(fmax((double)c, 0.0), 1.0);
    return (int)(255.99f * c);
}

