    V origin = vc(0.0f, 0.0f, 0.0f);
    float vph = 2.0f;
    float vpw = ((float)W / (float)H) * vph;
    float focal = 1.0f;
    V horiz = vc(vpw, 0.0f, 0.0f);
    V vert = vc(0.0f, vph, 0.0f);
    V llc = vsub(vsub(vsub(origin, vmul(horiz, 0.5f)), vmul(vert, 0.5f)), vc(0.0f, 0.0f, focal));
    V sc = vc(0.0f, -0.5f, -5.0f);
    float sr = 1.0f;
    V light = vnorm(vc(1.0f, 1.0f, -1.0f));
    FILE *f = fopen("reconstructed.ppm", "w");
    int i, j;
    if (!f) return 1;
    fprintf(f, "P3\n%d %d\n255\n", W, H);
    for (j = 0; j < H; j++) {
        for (i = 0; i < W; i++) {
            float u = (float)i / (float)(W - 1);
            float v = (float)j / (float)(H - 1);
            V dir = vadd(vadd(vsub(vmul(vert, 1.0f - v), origin), vmul(horiz, u)), llc);
            V col = trace(sc, sr, light, ray_create(origin, dir));
            fprintf(f, "%d %d %d\n", q(col.x), q(col.y), q(col.z));
        }
    }
    fclose(f);
    return 0;
}

